    46	function PrivateNotesListPage({report, personalDetailsList, accountID: sessionAccountID}: PrivateNotesListPageProps) {
    47	    const route = useRoute<RouteProp<PrivateNotesNavigatorParamList, typeof SCREENS.PRIVATE_NOTES.LIST>>();
    48	    const backTo = route.params.backTo;
    49	    const styles = useThemeStyles();
    50	    const {translate} = useLocalize();
    51	    const getAttachmentValue = useCallback((item: NoteListItem) => ({reportID: item.reportID, accountID: Number(item.accountID), type: CONST.ATTACHMENT_TYPE.NOTE}), []);
    52	
    53	    /**
    54	     * Gets the menu item for each workspace
    55	     */
    56	    function getMenuItem(item: NoteListItem) {
    57	        return (
    58	            <AttachmentContext.Provider value={getAttachmentValue(item)}>
    59	                <MenuItemWithTopDescription
    60	                    key={item.title}
    61	                    description={item.title}
    62	                    title={item.note}
    63	                    onPress={item.action}
    64	                    shouldShowRightIcon={!item.disabled}
    65	                    numberOfLinesTitle={0}
    66	                    shouldRenderAsHTML
    67	                    brickRoadIndicator={item.brickRoadIndicator}
    68	                    disabled={item.disabled}
    69	                    shouldGreyOutWhenDisabled={false}
    70	                />
    71	            </AttachmentContext.Provider>
    72	        );
    73	    }
    74	
    75	    /**
    76	     * Returns a list of private notes on the given chat report
    77	     */
    78	    const privateNotes = useMemo(() => {
    79	        const privateNoteBrickRoadIndicator = (accountID: number) => (report.privateNotes?.[accountID].errors ? CONST.BRICK_ROAD_INDICATOR_STATUS.ERROR : undefined);
    80	        return Object.keys(report.privateNotes ?? {}).map((accountID: string) => {
    81	            const privateNote = report.privateNotes?.[Number(accountID)];
    82	            return {
    83	                reportID: report.reportID,
    84	                accountID,
    85	                title: Number(sessionAccountID) === Number(accountID) ? translate('privateNotes.myNote') : personalDetailsList?.[accountID]?.login ?? '',
