    87	                brickRoadIndicator: privateNoteBrickRoadIndicator(Number(accountID)),
    88	                note: privateNote?.note ?? '',
    89	                disabled: Number(sessionAccountID) !== Number(accountID),
    90	            };
    91	        });
    92	    }, [report, personalDetailsList, sessionAccountID, translate, backTo]);
    93	
    94	    return (
    95	        <ScreenWrapper
    96	            includeSafeAreaPaddingBottom={false}
    97	            testID={PrivateNotesListPage.displayName}
    98	        >
    99	            <HeaderWithBackButton
   100	                title={translate('privateNotes.title')}
   101	                shouldShowBackButton
   102	                onBackButtonPress={() => Navigation.goBack(ROUTES.REPORT_WITH_ID_DETAILS.getRoute(report.reportID, backTo))}
   103	                onCloseButtonPress={() => Navigation.dismissModal()}
   104	            />
   105	            <Text style={[styles.mb5, styles.ph5]}>{translate('privateNotes.personalNoteMessage')}</Text>
   106	            <ScrollView
   107	                contentContainerStyle={styles.flexGrow1}
   108	                bounces={false}
   109	            >
   110	                {privateNotes.map((item) => getMenuItem(item))}
   111	            </ScrollView>
   112	        </ScreenWrapper>
   113	    );
   114	}
