    91	            editedNote = ReportActions.handleUserDeletedLinksInHtml(privateNote.trim(), Parser.htmlToMarkdown(originalNote).trim());
    92	            ReportActions.updatePrivateNotes(report.reportID, Number(route.params.accountID), editedNote);
    93	        }
    94	
    95	        // We want to delete saved private note draft after saving the note
    96	        debouncedSavePrivateNote('');
    97	
    98	        Keyboard.dismiss();
    99	        if (!Object.values<Note>({...report.privateNotes, [route.params.accountID]: {note: editedNote}}).some((item) => item.note)) {
